    if(g>=3){
    const SH=[['大きな','犬',['歩く','ゆっくり'],'大きな 犬が ゆっくり 歩く。'],['白い','花',['さいた','庭に'],'庭に 白い 花が さいた。'],['ゆっくり','歩く',['犬が','大きな'],'大きな 犬が ゆっくり 歩く。'],['きれいな','声',['うたう','姉が'],'姉が きれいな 声で うたう。'],['あまい','ケーキ',['食べた','おやつに'],'おやつに あまい ケーキを 食べた。'],['はやく','走る',['うさぎが','野原を'],'うさぎが 野原を はやく 走る。']];
    // 文の中の 候補は 2つしか ないので、ほかの 文の ことばも 1つ まぜて 4たくにする。
    Q.push(()=>{const it=SH[this.rand(0,SH.length-1)],rest=SH.filter(x=>x[3]!==it[3]),other=rest[this.rand(0,rest.length-1)];return mc('「'+it[3]+'」で 「'+it[0]+'」が くわしく して いる ことばは？',it[1],it[2].concat([other[1],other[0]]),'「'+it[0]+'」は 「'+it[1]+'」を くわしく する ことば（しゅうしょくご）だよ。');});
    }
