  pickGoi(p){const g=this.effectiveGrade(p),stage=this.topicStage(p,'goi');const mc=(pr,ans,pool,ex)=>({topic:'goi',mode:'choices',prompt:pr,answer:ans,choices:this.pick4(ans,pool),explanation:ex});const Q=[];
    const H=[['大きい','小さい'],['たかい','ひくい'],['ながい','みじかい'],['あつい','さむい'],['はやい','おそい'],['あかるい','くらい'],['おもい','かるい'],['つよい','よわい'],['ひろい','せまい'],['あたらしい','ふるい'],['うえ','した'],['まえ','うしろ'],['みぎ','ひだり'],['あさ','よる'],['いく','くる'],['あける','しめる']];
    Q.push(()=>{const it=H[this.rand(0,H.length-1)];const flip=Math.random()<0.5;const w=flip?it[1]:it[0],ans=flip?it[0]:it[1];const others=this.shuffle(H.filter(x=>x!==it)).slice(0,3).map(x=>x[this.rand(0,1)]);return mc('「'+w+'」の はんたいの ことばは？',ans,others,'「'+w+'」の はんたいは 「'+ans+'」だよ。');});
    const N=[['くだもの',['りんご','みかん','ばなな','ぶどう']],['どうぶつ',['いぬ','ねこ','うま','ぞう']],['のりもの',['バス','でんしゃ','ふね','ひこうき']],['やさい',['にんじん','だいこん','きゅうり','なす']],['いろ',['あか','あお','しろ','きいろ']],['てんき',['はれ','あめ','くもり','ゆき']]];
    Q.push(()=>{const it=N[this.rand(0,N.length-1)];const members=this.shuffle(it[1].slice()).slice(0,3);const others=this.shuffle(N.filter(x=>x!==it)).slice(0,3).map(x=>x[0]);return mc(members.join('・')+' は なんの なかま？',it[0],others,members.join('・')+' は みんな '+it[0]+' の なかまだよ。');});
    Q.push(()=>{const it=N[this.rand(0,N.length-1)];const other=this.shuffle(N.filter(x=>x!==it))[0];const odd=other[1][this.rand(0,other[1].length-1)];const members=this.shuffle(it[1].slice()).slice(0,3);return mc('なかまはずれは どれ？',odd,members,'「'+odd+'」は '+other[0]+'。ほかは みんな '+it[0]+' の なかまだよ。');});
    const counters=[['えんぴつ',['いっぽん','にほん','さんぼん']],['本',['いっさつ','にさつ','さんさつ']],['かみ',['いちまい','にまい','さんまい']],['ねこ',['いっぴき','にひき','さんびき']],['車',['いちだい','にだい','さんだい']],['コップの 水',['いっぱい','にはい','さんばい']],['りんご',['いっこ','にこ','さんこ']],['鳥',['いちわ','にわ','さんわ']],['くつ',['いっそく','にそく','さんぞく']],['ようふく',['いっちゃく','にちゃく','さんちゃく']],['家',['いっけん','にけん','さんげん']],['人',['ひとり','ふたり','さんにん']]];
    Q.push(()=>{const it=counters[this.rand(0,counters.length-1)],n=this.rand(1,3),answer=it[1][n-1],pool=this.shuffle(counters.filter(x=>x!==it)).slice(0,3).map(x=>x[1][n-1]);return{topic:'goi',mode:'choices',subtype:'counter',prompt:it[0]+'を '+n+' 数える とき、どう よむ？',answer:answer,choices:this.pick4(answer,pool),explanation:it[0]+'は '+n+'で 「'+answer+'」と 数えるよ。'};});
    const greetings=[['あさ、先生に 会いました。','おはようございます',['こんばんは','さようなら','いただきます']],['ひる、友だちに 会いました。','こんにちは',['おやすみなさい','ごちそうさま','いってきます']],['よる、近所の 人に 会いました。','こんばんは',['おはようございます','ただいま','いただきます']],['学校から 帰る とき、先生に 言います。','さようなら',['おはよう','おかえりなさい','ごちそうさま']],['ごはんを 食べる 前に 言います。','いただきます',['ただいま','いってらっしゃい','おやすみなさい']],['家に 帰ってきた ときに 言います。','ただいま',['いってきます','こんにちは','さようなら']]];
    Q.push(()=>{const it=greetings[this.rand(0,greetings.length-1)];return{topic:'goi',mode:'choices',subtype:'greeting',prompt:it[0]+' あう あいさつは？',answer:it[1],choices:this.pick4(it[1],it[2]),explanation:it[0]+'「'+it[1]+'」と あいさつするよ。'};});
    const feelings=[['大切な えんぴつを なくした。','かなしい','大切な ものを なくしたから'],['れんしゅうして さか上がりが できた。','うれしい','がんばって できるように なったから'],['くらい みちで 大きな 音が した。','こわい','見えない ところで 大きな 音が したから'],['友だちが じゅんばんを ぬかした。','おこっている','きまりを まもって もらえなかったから'],['あしたは えんそくに 行く。','たのしみ','あしたの えんそくを まっているから'],['みんなの 前で はじめて はっぴょうする。','どきどきする','うまく できるか しんぱいだから']];
    Q.push(()=>{const it=feelings[this.rand(0,feelings.length-1)],others=this.shuffle(feelings.filter(x=>x!==it)).slice(0,3).map(x=>x[1]);return{topic:'goi',mode:'choices',subtype:'feeling-reason',prompt:it[0]+' どんな 気もち？',answer:it[1],choices:this.pick4(it[1],others),explanation:'「'+it[2]+'」ので '+it[1]+' 気もちだと 考えられるよ。'};});
    if(g>=3){
    const KW=[['さるも木から落ちる','じょうずな 人でも しっぱいする ことが ある'],['犬も歩けばぼうに当たる','出歩くと 思いがけない ことに 出会う'],['石の上にも三年','がまんして つづければ うまくいく'],['ねこの手もかりたい','とても いそがしい'],['花よりだんご','見た目より 役に立つ ものが よい'],['口がかるい','ひみつを すぐ 話して しまう'],['頭をひねる','いっしょうけんめい 考える'],['耳にたこができる','同じ 話を なんども 聞かされる'],['馬が合う','気が 合う'],['手をかす','手つだう']];
    Q.push(()=>{const it=KW[this.rand(0,KW.length-1)];const others=this.shuffle(KW.filter(x=>x!==it)).slice(0,3).map(x=>x[1]);return mc('「'+it[0]+'」の いみは？',it[1],others,'「'+it[0]+'」は 「'+it[1]+'」と いう いみだよ。');});
    const JW=['あき','あさ','あめ','いえ','いぬ','いす','うた','うみ','えき','かい','かき','かさ','きた','くも','さかな','しか','すいか','そら','たけ','つき','ねこ','はし','はな','ふね','ほし','みかん','むし','やま','ゆき'];
    Q.push(()=>{const ws=this.shuffle(JW.slice()).slice(0,4);const sorted=ws.slice().sort();const first=Math.random()<0.5;const ans=first?sorted[0]:sorted[3];return{topic:'goi',mode:'choices',prompt:ws.join('・')+' を 国語じてんの じゅんに ならべると、いちばん '+(first?'はじめ':'あと')+'に 出てくるのは？',answer:ans,choices:this.shuffle(ws.slice()),explanation:'五十音じゅんに ならべると '+sorted.join('→')+' だよ。'};});
    }
    return Q[this.rand(0,Q.length-1)]();}
