    {g:3,t:'町の 図書館は 火曜日から 日曜日まで 開いています。月曜日は 休みです。',q:'図書館が 休みの 曜日は？',a:'月曜日',c:['火曜日','土曜日','日曜日'],e:'「月曜日は 休みです」と 書いて あるよ。'},
    {g:3,t:'植物の 根には、水や 養分を 取り入れる はたらきと、からだを 支える はたらきがあります。',q:'根の はたらきでは ない ものは？',a:'花を さかせる',c:['水を 取り入れる','養分を 取り入れる','からだを 支える'],e:'本文には、水や 養分を 取り入れ、からだを 支えると あるよ。'},
    {g:3,t:'学校では 紙を へらすため、使い終わった プリントの うらも メモに 使っています。',q:'プリントの うらを 使う 目的は？',a:'紙を へらすため',c:['字を 大きく 書くため','色を ぬるため','宿題を ふやすため'],e:'はじめに「紙を へらすため」と 目的が 書かれているよ。'},
    {g:3,t:'雨が 強く なったので、遠足は 金曜日から 月曜日に かわりました。',q:'遠足は いつに かわった？',a:'月曜日',c:['木曜日','金曜日','日曜日'],e:'「金曜日から 月曜日に かわりました」と あるよ。'},
    {g:3,t:'海の 水は 太陽に あたると 水じょう気になり、空へ 上がります。それが 冷えると 雲になります。',q:'水じょう気が 冷えると 何になる？',a:'雲',c:['雨だけ','風','土'],e:'「それが 冷えると 雲になります」と 書いて あるよ。'},
    {g:3,t:'アリは なかまと においで 話を します。えさを 見つけると、においの みちを 作って なかまに 知らせます。',q:'アリが なかまに 知らせる やりかたは？',a:'においの みち',c:['大きな 声','光','はねの 音'],e:'「においの みちを 作って なかまに 知らせます」と あるよ。'},
    {g:3,t:'牛にゅうから バターや チーズが 作られます。どちらも 牛にゅうの あぶらや えいようを あつめた 食べ物です。',q:'バターや チーズの もとに なる ものは？',a:'牛にゅう',c:['たまご','だいず','こむぎ'],e:'「牛にゅうから バターや チーズが 作られます」と あるよ。'},
    {g:3,t:'雪の おおい 土地の 家は、やねの かたむきが 急です。雪が しぜんに すべり落ちるように くふうして います。',q:'やねの かたむきを 急に する わけは？',a:'雪を すべり落とすため',c:['風を ふせぐため','日かげを 作るため','家を 高く 見せるため'],e:'「雪が しぜんに すべり落ちるように」と 目てきが 書いて あるよ。'},
    {g:3,t:'こん虫の からだは 頭・むね・はらの 三つに 分かれて います。あしは むねから 六本 出て います。',q:'こん虫の あしは 何本？',a:'六本',c:['四本','八本','十本'],e:'「あしは むねから 六本」と あるよ。'},
    {g:3,t:'ゆうかは 三時に 出発して、四十分 歩いて じんじゃに つきました。帰りは バスに のりました。',q:'じんじゃに ついた 時こくは？',a:'三時四十分',c:['三時二十分','四時四十分','四時'],e:'三時から 四十分 歩いたので 三時四十分。'},
    {g:3,t:'たねから めが 出るには、水と 空気と ちょうどよい あたたかさが いります。',q:'たねから めが 出るのに いらない ものは？',a:'ひりょう',c:['水','空気','ちょうどよい あたたかさ'],e:'本文には 水・空気・あたたかさが いると あるよ。ひりょうは 書かれて いないね。'}
  ];const pool=D.filter(x=>x.g<=g);const early=stage<=2?pool.filter(x=>x.g===1):(stage>=5?pool.filter(x=>x.g===g):pool);const use=early.length?early:pool;const it=use[this.rand(0,use.length-1)];return{topic:'dokkai',mode:'choices',prompt:it.t+'　もんだい： '+it.q,answer:it.a,choices:this.pick4(it.a,it.c),explanation:it.e};}
  pickEigo(p){const stage=this.topicStage(p,'eigo');const mc=(pr,ans,pool,ex,speak)=>({topic:'eigo',mode:'choices',prompt:pr,answer:ans,choices:this.pick4(ans,pool),explanation:ex,speakChoices:!!speak});const Q=[];
    const wq=L=>{const it=L[this.rand(0,L.length-1)],others=this.shuffle(L.filter(x=>x[0]!==it[0]));if(Math.random()<0.5)return mc('英語「'+it[0]+'」の いみは？',it[1],others.slice(0,3).map(x=>x[1]),'「'+it[0]+'」は 「'+it[1]+'」だよ。',false);return mc('「'+it[1]+'」を 英語で いうと？',it[0],others.slice(0,3).map(x=>x[0]),'「'+it[1]+'」は 英語で 「'+it[0]+'」。',true);};
    const C=[['red','あか'],['blue','あお'],['yellow','きいろ'],['green','みどり'],['black','くろ'],['white','しろ'],['pink','ピンク'],['orange','オレンジいろ'],['purple','むらさき'],['brown','ちゃいろ']];
    const NUM=[['one','1'],['two','2'],['three','3'],['four','4'],['five','5'],['six','6'],['seven','7'],['eight','8'],['nine','9'],['ten','10']];
    Q.push(()=>wq(C));
    Q.push(()=>wq(NUM));
    if(stage>=2){
    const W=[['dog','いぬ'],['cat','ねこ'],['bird','とり'],['fish','さかな'],['rabbit','うさぎ'],['monkey','さる'],['bear','くま'],['horse','うま'],['apple','りんご'],['banana','バナナ'],['milk','ぎゅうにゅう'],['egg','たまご'],['rice','ごはん'],['book','本'],['pen','ペン'],['bag','かばん'],['cap','ぼうし'],['ball','ボール'],['hand','て'],['eye','め']];
    Q.push(()=>wq(W));
    Q.push(()=>wq(W));
    }
    if(stage>=3){
    const G=[['あさ 会ったときの あいさつは？','Good morning.',['Good night.','Thank you.','Goodbye.'],'あさの あいさつは Good morning. だよ。'],
    ['ねる まえの あいさつは？','Good night.',['Good morning.','Hello.','Thank you.'],'ねる まえは Good night. だよ。'],
    ['「ありがとう」を 英語で いうと？','Thank you.',['Sorry.','Hello.','Goodbye.'],'ありがとうは Thank you. だよ。'],
    ['わかれる ときの あいさつは？','Goodbye.',['Hello.','Good morning.','Thank you.'],'わかれる ときは Goodbye. だよ。'],
    ['「こんにちは」に あたる あいさつは？','Hello.',['Goodbye.','Good night.','Sorry.'],'こんにちはは Hello. だよ。'],
    ['なまえを きく いいかたは？','What is your name?',['How are you?','How old are you?','What color do you like?'],'なまえを きくときは What is your name? だよ。'],
    ['「げんきですか」と きく いいかたは？','How are you?',['What is your name?','Good night.','See you.'],'げんきかどうかは How are you? と きくよ。']];
    Q.push(()=>{const it=G[this.rand(0,G.length-1)];return mc(it[0],it[1],it[2],it[3],true);});
    }
    if(stage>=4){const S=[['I like apples.','わたしは りんごが すきです。'],['I have a dog.','わたしは いぬを かっています。'],['This is my book.','これは わたしの 本です。'],['I can swim.','わたしは およげます。']];Q.push(()=>wq(S));}
    if(stage>=5){const R=[['How are you?','I am fine.',['Good night.','My name is Ken.','Thank you.']],['What is your name?','My name is Ken.',['I am ten.','Good morning.','I like blue.']],['What color do you like?','I like blue.',['I am fine.','See you.','It is a dog.']]];Q.push(()=>{const it=R[this.rand(0,R.length-1)];return mc('しつもん「'+it[0]+'」に あう こたえは？',it[1],it[2],it[0]+' には '+it[1]+' と こたえるよ。',true);});}
    const q=Q[this.rand(0,Q.length-1)]();q.difficulty=stage;return q;}
""";
